import { createFileRoute, redirect } from '@tanstack/react-router';
import AdvancedSearch from '@/pages/search/AdvancedSearch';
import { canUseAdvancedSearch } from '@/utils/advancedSearchAccess';

export const Route = createFileRoute('/_auth/search/advanced')({
  beforeLoad: () => {
    if (!canUseAdvancedSearch()) throw redirect({ to: '/' });
  },
  component: AdvancedSearch,
});
